import type { StudioMembership } from '@/lib/context/active-studio'
import type { UserPinnedItem } from '@/lib/pinned-items/pinned'

interface AppSidebarProps {
  plan: PlanTier
  studioName: string
  studioLogoUrl?: string | null
  role: NavRole
  locationCount: number
  /** Serialized from server — Set<string> → JSON array → passed as prop */
  permissionKeys?: string[]
  /** Dynamic badge counts from server (inbox, calendar, clients, inventory) */
  dynamicBadges?: DynamicBadgeCounts
  /** S22: pinned items for Favorites section */
  pinnedItems?: UserPinnedItem[]
  // Kept as optional for call-site compat. Sidebar no longer renders the
  // studio switcher or booking-link widget in the header (moved to top bar /
  // to-be-decided placement per UX direction).
  studioSlug?: string
  allMemberships?: StudioMembership[]
  currentStudioId?: string
}

export function AppSidebar({
  plan,
  studioLogoUrl,
  role,
  locationCount,
  permissionKeys = [],
  dynamicBadges = {},
  pinnedItems = [],
}: AppSidebarProps) {
  const permissions = useMemo(() => new Set(permissionKeys), [permissionKeys])

  const navGroups = useMemo(() => {
    return APP_NAV
      .filter((group) => !(group.condition === 'multi-location' && locationCount <= 1))
      .map((group) => ({
        ...group,
        items: group.items.filter((item) => {
          if (!item.requiredRoles.includes(role)) return false
          if (item.requiredPermission && !permissions.has(item.requiredPermission)) return false
          return true
        }),
--
      <SidebarHeader className="border-b border-sidebar-border/60 px-3 py-3">
        <div className="flex items-center gap-2 group-data-[collapsible=icon]:justify-center">
          {studioLogoUrl ? (
            // eslint-disable-next-line @next/next/no-img-element
            <img
              src={studioLogoUrl}
              alt="InkOS"
              className="h-8 w-8 shrink-0 rounded-md object-cover"
            />
          ) : (
            /* InkOS brand mark — italic `i` in Onyx tile per brand book */
            <div className="flex h-8 w-8 shrink-0 items-center justify-center rounded-md bg-foreground text-background">
              <span className="font-serif-italic text-xl leading-none">i</span>
            </div>
          )}
          <div className="flex min-w-0 flex-col leading-tight group-data-[collapsible=icon]:hidden">
            <span className="truncate text-[13px] font-bold tracking-tight text-sidebar-foreground">
              InkOS
            </span>
            <span className="truncate text-[10px] font-medium uppercase tracking-[0.08em] text-stone-brand">
              Studio OS
            </span>
          </div>
        </div>
      </SidebarHeader>

      {/* ── Nav groups ────────────────────────────────────────── */}
      <SidebarContent className="gap-0 px-2 py-3">
        {navGroups.map((group, idx) => (
          <SidebarNavGroup
            key={group.label ?? '_unlabeled'}
            group={group}
            plan={plan}
            isFirst={idx === 0}
            dynamicBadges={dynamicBadges}
          />
        ))}

        {/* S22: Favorites */}
        <SidebarFavorites pinnedItems={pinnedItems} />
      </SidebarContent>
    </Sidebar>
  )
}

  /** Dynamic badge counts from server (inbox, calendar, clients, inventory) */
  dynamicBadges?: DynamicBadgeCounts
  /** S22: pinned items for Favorites section */
  pinnedItems?: UserPinnedItem[]
  // Kept as optional for call-site compat. Sidebar no longer renders the
  // studio switcher or booking-link widget in the header (moved to top bar /
  // to-be-decided placement per UX direction).
  studioSlug?: string
  allMemberships?: StudioMembership[]
  currentStudioId?: string
}

